using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class PipMilestoneTests
{
 class User(int employee=6,bool hr=false):ICurrentUser{public string Email=>$"pip{employee}@example.local";public int? EmployeeId=>employee;public int UserId=>employee;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static PerfService S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,u,new(d,u),c,a,new(d,u,c));}
 static async Task<int> Setup(AppDbContext d){var c=new PerfCycle{Name="PIP test",Status=CycleStatus.Closed};d.Add(c);await d.SaveAsync();var a=new PerfAppraisal{EmployeeId=6,CycleId=c.Id,FinalScore=4};d.Add(a);await d.SaveAsync();return a.Id;}
 [Fact]public async Task EmployeeMayRecordEvidenceButCannotConfirmOwnCompletion(){await using var d=await Db();var id=await Setup(d);var hr=S(d,new(1,true));var day=new AppClock(TimeProvider.System).Today.AddDays(7);await hr.AddMilestoneAsync(id,"Quality checks","Complete 10 reviewed samples",day,"Coaching support");var m=Assert.Single((await S(d).PipAsync(id)).Milestones);await S(d).UpdateMilestoneAsync(m.Id,60,"Six reviewed samples","Update");await Assert.ThrowsAsync<DomainException>(()=>S(d).UpdateMilestoneAsync(m.Id,100,"Done","Completed"));await hr.UpdateMilestoneAsync(m.Id,100,"Ten samples verified","Completed");Assert.Equal("Completed",(await d.Set<PipMilestone>().FindAsync(m.Id))!.Status);Assert.Equal(4,(await d.Set<PerfAppraisal>().FindAsync(id))!.FinalScore);Assert.Equal(3,(await hr.PipAsync(id)).Progress.Count);await Assert.ThrowsAsync<DomainException>(()=>S(d).UpdateMilestoneAsync(m.Id,50,"Later","Update"));}
 [Fact]public async Task ScopeSelfReviewAndRequiredMeasuresAreEnforced(){await using var d=await Db();var id=await Setup(d);var day=new AppClock(TimeProvider.System).Today.AddDays(1);await Assert.ThrowsAsync<DomainException>(()=>S(d).AddMilestoneAsync(id,"Test","Measure",day,"Reason"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,true)).AddMilestoneAsync(id,"Test","Measure",day,"Reason"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(1,true)).AddMilestoneAsync(id,"Test","",day,"Reason"));await Assert.ThrowsAsync<DomainException>(()=>S(d,new(7)).PipAsync(id));Assert.Empty(await d.Set<PipMilestone>().ToListAsync());}
 [Fact]public async Task EvidenceAppendOnlyAndCompletionRequiresHundredPercent(){await using var d=await Db();var id=await Setup(d);var hr=S(d,new(1,true));await hr.AddMilestoneAsync(id,"Test","Measure",new AppClock(TimeProvider.System).Today,"Reason");var m=await d.Set<PipMilestone>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>hr.UpdateMilestoneAsync(m.Id,99,"Not complete","Completed"));await hr.UpdateMilestoneAsync(m.Id,0,"Cancelled by reviewer","Cancelled");Assert.Equal(2,await d.Set<PipProgress>().CountAsync());var e=await d.Set<PipProgress>().FirstAsync();e.Note="rewritten";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
}
